A class is a blueprint or template that defines the properties (attributes) and behaviors (methods) of a specific type of object. An object is an instance of a class. When a class is defined, no memory is allocated until an object of that class is created. 

Example in C++:
```cpp
#include <iostream>
using namespace std;

// Class definition
class Car {
public:
    string brand;
    string model;
    int year;

    void displayInfo() {
        cout << "Brand: " << brand << ", Model: " << model << ", Year: " << year << endl;
    }
};

int main() {
    // Object creation
    Car car1;
    car1.brand = "Toyota";
    car1.model = "Corolla";
    car1.year = 2020;

    car1.displayInfo(); // Output: Brand: Toyota, Model: Corolla, Year: 2020
    return 0;
}
```
Here, `Car` is a class with attributes and a method. `car1` is an object of the `Car` class.

```cpp
#include <iostream>
using namespace std;

class Complex {
private:
    float real;
    float imag;

public:
    Complex(float r = 0, float i = 0) : real(r), imag(i) {}

    // Friend function declaration for operator overloading
    friend Complex operator+(const Complex& c1, const Complex& c2);

    void display() const {
        cout << real << " + " << imag << "i" << endl;
    }
};

// Definition of the friend function
Complex operator+(const Complex& c1, const Complex& c2) {
    return Complex(c1.real + c2.real, c1.imag + c2.imag);
}

int main() {
    Complex c1(3.5, 2.5);
    Complex c2(1.5, 4.5);

    Complex sum = c1 + c2; // Calls the overloaded + operator

    cout << "Complex Number 1: "; c1.display();
    cout << "Complex Number 2: "; c2.display();
    cout << "Sum: "; sum.display();

    return 0;
}
```

**Types of Inheritance in C++:**
1. **Single Inheritance:** A derived class inherits from one base class.
2. **Multiple Inheritance:** A derived class inherits from more than one base class.
3. **Multilevel Inheritance:** A derived class acts as a base class for another derived class.
4. **Hierarchical Inheritance:** Multiple derived classes inherit from a single base class.
5. **Hybrid Inheritance:** A combination of two or more types of inheritance.

**Example Program (Single Inheritance):**
```cpp
#include <iostream>
using namespace std;

class Animal { // Base Class
public:
    void eat() {
        cout << "Eating..." << endl;
    }
};

class Dog : public Animal { // Derived Class
public:
    void bark() {
        cout << "Barking..." << endl;
    }
};

int main() {
    Dog myDog;
    myDog.eat();  // Inherited method
    myDog.bark(); // Own method
    return 0;
}
```

```cpp
#include <iostream>
using namespace std;

// Function template to find the largest of two numbers
template <typename T>
T findLargest(T a, T b) {
    return (a > b) ? a : b;
}

int main() {
    int int1 = 10, int2 = 20;
    float float1 = 15.5, float2 = 10.2;
    char char1 = 'A', char2 = 'Z';

    cout << "Largest integer: " << findLargest(int1, int2) << endl;
    cout << "Largest float: " << findLargest(float1, float2) << endl;
    cout << "Largest character: " << findLargest(char1, char2) << endl;

    return 0;
}
```

Associative containers are designed for fast retrieval of data based on keys.

1. **Set:** Stores unique elements sorted by their value. The value itself is the key.
2. **Multiset:** Similar to Set, but allows duplicate values.
3. **Map:** Stores key-value pairs. Keys are unique and sorted. 
4. **Multimap:** Similar to Map, but allows multiple elements to have the same key.

**Example using Map:**
```cpp
#include <iostream>
#include <map>
using namespace std;

int main() {
    map<int, string> studentMap;
    // Inserting elements
    studentMap[1] = "Alice";
    studentMap[2] = "Bob";
    studentMap[1] = "Charlie"; // Overwrites "Alice" because keys are unique

    cout << "Map contents:" << endl;
    for (auto const& pair : studentMap) {
        cout << "Roll No: " << pair.first << ", Name: " << pair.second << endl;
    }
    return 0;
}
```

```cpp
#include <iostream>
#include <string>
using namespace std;

class Book {
private:
    int bookId;
    string title;
    string author;
    float price;
    float discount;
    float finalPrice;

public:
    // Constructor without discount
    Book(int id, string t, string a, float p) {
        bookId = id;
        title = t;
        author = a;
        price = p;
        discount = 0;
        finalPrice = p;
    }

    // Constructor with discount
    Book(int id, string t, string a, float p, float d) {
        bookId = id;
        title = t;
        author = a;
        price = p;
        discount = d;
        finalPrice = price - (price * (discount / 100.0));
    }

    void display() const {
        cout << "\nBook ID: " << bookId
             << "\nTitle: " << title
             << "\nAuthor: " << author
             << "\nOriginal Price: $" << price;
        if (discount > 0) {
            cout << "\nDiscount: " << discount << "%"
                 << "\nDiscounted Price: $" << finalPrice;
        }
        cout << "\n--------------------------" << endl;
    }
};

int main() {
    // Customer provides details without discount
    Book book1(101, "C++ Primer", "Stanley B. Lippman", 50.0);
    cout << "Details of Book 1:";
    book1.display();

    // Customer provides details with a 10% discount
    Book book2(102, "Clean Code", "Robert C. Martin", 40.0, 10.0);
    cout << "Details of Book 2:";
    book2.display();

    return 0;
}
```

```cpp
#include <iostream>
using namespace std;

class ShapeArea {
public:
    // Function to calculate and print the area of a square
    // Takes one parameter: side of the square
    void printArea(double side) {
        double area = side * side;
        cout << "Area of Square with side " << side << " is: " << area << endl;
    }

    // Function to calculate and print the area of a rectangle
    // Takes two parameters: length and breadth
    void printArea(double length, double breadth) {
        double area = length * breadth;
        cout << "Area of Rectangle with length " << length 
             << " and breadth " << breadth << " is: " << area << endl;
    }
};

int main() {
    ShapeArea shape;

    // Calling method for square
    shape.printArea(5.0);

    // Calling method for rectangle
    shape.printArea(4.5, 6.0);

    return 0;
}
```
